109	struct PhaseCompositions<MergeStrategy::Stufe2_PrueflingReplace> {
110	    using EngineA = comp::HotComposition;
111	    using EngineB = comp::HotPrtStufe2ReplaceComposition;
112	};
113	template <>
114	struct PhaseCompositions<MergeStrategy::Stufe3_FullJoin> {
115	    using EngineA = comp::HotComposition;
116	    using EngineB = comp::HotPrtStufe3FullJoinComposition;
