121	/// Konformitaets-Felder werden nicht in die 12-Spalten-CSV projiziert (der Exporter kennt sie nicht).
122	[[nodiscard]] inline PermutationOutcome to_permutation_outcome(kat::KatalogPermutationOutcome const& ko) {
123	    PermutationOutcome po;
124	    po.axis_id          = ko.axis_id;
